package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.time.Instant;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Static projections + real REQUIRED templates, modeled executor/manager, no SQL engine. */
class SqlServerAuditStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",OTHER="cc000000-0000-4000-8000-000000000001",TIME="2026-11-04T12:00:00.123456Z";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerAuditStore store=new SqlServerAuditStore(executor,manager);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/trace");
 final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerAuditStoreTest(){tenant();when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());calls.add(inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals("a".repeat(64),c.tokenHash());args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void tenant(){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("AUD"),"a".repeat(64)));request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));}
 void platform(){request.removeAttribute("health.tenant");request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SOP"),"a".repeat(64)));}
 static Map<String,Object> audit(long id){var r=new LinkedHashMap<String,Object>();r.put("id",id);r.put("actorId",null);r.put("action","CHANGE");r.put("targetId","opaque-not-uuid");r.put("metadata",null);r.put("createdAt",TIME);return r;}
 static Map<String,Object> event(long id,String tenant){var r=audit(id);r.put("tenantId",tenant);r.put("requestId",null);for(String k:List.of("method","route","sourceIp","userAgent","actorRoles","beforeState","afterState","resourceType","actorName","actorEmail","tenantName"))r.put(k,null);return r;}
 static Map<String,Object> trace(String tenant){var r=new LinkedHashMap<String,Object>();r.put("id",ID);r.put("tenantId",tenant);r.put("actorId",null);r.put("method","GET");r.put("route","/api/test");r.put("sourceIp","127.0.0.1");r.put("userAgent","");r.put("status",200);r.put("durationMs",Long.MAX_VALUE);r.put("createdAt",TIME);r.put("actorName",null);return r;}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());}
 @Test void fourDescriptorsAndExactBindsWithoutExtraQueries(){rows(List.of(audit(1)));store.list(request,0);rows(List.of());store.events(request,"  ",ID,"Custom",ID,TIME,null,Long.MAX_VALUE,201);rows(List.of(trace(TENANT)));store.requests(request,200,999,"Case");results.add(new SqlServerExecutor.Result(List.of(List.of(trace(TENANT)),List.of()),List.of()));store.journey(request,ID);assertEquals(List.of(SqlServerProcedure.AUDIT_LIST,SqlServerProcedure.TRACE_EVENTS,SqlServerProcedure.TRACE_REQUESTS,SqlServerProcedure.TRACE_JOURNEY),calls);assertEquals(List.of(1),args.getFirst());assertEquals(Arrays.asList(null,ID,"Custom",ID,Instant.parse(TIME),null,Long.MAX_VALUE,200),args.get(1));assertEquals(List.of(200,999,"Case"),args.get(2));assertEquals(List.of(ID),args.getLast());}
 @Test void eventPaginationEmptyExactExtraAndLongCursor(){for(int size:List.of(1,200)){for(int count:List.of(0,size,size+1)){var input=new ArrayList<Map<String,Object>>();for(int i=0;i<count;i++)input.add(event(Long.MAX_VALUE-i,TENANT));rows(input);var out=store.events(request,null,null,null,null,null,null,-1,size);var items=(List<?>)out.get("items");assertEquals(Math.min(size,count),items.size());assertEquals(count>size,out.get("hasMore"));assertEquals(count==0?0L:Long.MAX_VALUE-Math.min(size,count)+1,out.get("nextCursor"));assertEquals(0L,args.getLast().get(6));assertEquals(size,args.getLast().get(7));assertThrows(UnsupportedOperationException.class,items::clear);}}}
 @Test void journeyTwoResultsetsTrims201AndPlatformAllowsDifferentTenant(){platform();var steps=new ArrayList<Map<String,Object>>();for(int i=0;i<201;i++)steps.add(event(i+1,OTHER));results.add(new SqlServerExecutor.Result(List.of(List.of(trace(null)),steps),List.of()));var result=store.journey(request,ID);assertEquals(200,((List<?>)result.get("steps")).size());assertEquals(1,calls.size());assertEquals(12,result.size());results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));assertEquals(404,assertThrows(ApiException.class,()->store.journey(request,ID)).status);}
 @Test void jsonNullScalarsPrecisionAndDeepImmutableProjection(){var nested=new LinkedHashMap<String,Object>();var array=new ArrayList<Object>(Arrays.asList(null,new BigDecimal("12345678901234567890.123"),true));nested.put("values",array);var e=event(1,null);e.put("metadata",nested);e.put("beforeState","text");e.put("afterState",false);e.put("passwordHash","private");rows(List.of(e));var out=store.events(request,null,null,null,null,null,null,0,1);var row=(Map<String,Object>)((List<?>)out.get("items")).getFirst();assertEquals(19,row.size());assertFalse(row.containsKey("passwordHash"));assertNull(row.get("actorName"));var meta=(Map<String,Object>)row.get("metadata");var values=(List<?>)meta.get("values");assertNull(values.getFirst());assertEquals(array.get(1),values.get(1));assertThrows(UnsupportedOperationException.class,values::clear);assertThrows(UnsupportedOperationException.class,meta::clear);array.clear();assertEquals(3,values.size());assertThrows(UnsupportedOperationException.class,row::clear);}
 @Test void invalidJsonTypesNanCyclesAndNonStringKeysFailClosed(){var cycle=new ArrayList<>();cycle.add(cycle);for(Object json:List.of(new Object(),Double.NaN,Map.of(1,"bad"),cycle)){var e=event(1,TENANT);e.put("metadata",json);rows(List.of(e));safe(()->store.events(request,null,null,null,null,null,null,0,10));assertEquals("rollback",manager.events.getLast());}}
 @Test void unicodeAndFiltersTemporalPrecisionValidateBeforeExecutor(){rows(List.of());store.events(request,"x".repeat(99)+"\ud83e\uddb7",null,null,null,null,null,0,1);assertEquals(99,((String)args.getFirst().getFirst()).length());for(String date:List.of("bad","2026-11-04T00:00:00.123456789Z"))assertEquals(400,assertThrows(ApiException.class,()->store.events(request,null,null,null,null,date,null,0,1)).status);assertEquals(400,assertThrows(ApiException.class,()->store.events(request,null,"bad",null,null,null,null,0,1)).status);assertEquals(400,assertThrows(ApiException.class,()->store.events(request,null,null,"x".repeat(61),null,null,null,0,1)).status);assertEquals(400,assertThrows(ApiException.class,()->store.requests(request,1,0,"x".repeat(251))).status);assertEquals(1,calls.size());}
 @Test void cardinalityColumnsTypesAndCrossTenantRollback(){for(var row:List.of(event(1,OTHER),new LinkedHashMap<String,Object>())){rows(List.of(row));safe(()->store.events(request,null,null,null,null,null,null,0,1));}var bad=trace(TENANT);bad.put("status",200L);rows(List.of(bad));safe(()->store.requests(request,10,0,null));rows(List.of(trace(OTHER)));safe(()->store.requests(request,10,0,null));rows(List.of(audit(1),audit(2)));safe(()->store.list(request,1));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.list(request,10));var invalid=audit(1);invalid.put("createdAt","2026-11-04T00:00:00+00:00");rows(List.of(invalid));safe(()->store.list(request,10));}
 @Test void directAuthorityRejectsMissingActorWrongHostAndPlatformList(){request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->store.requests(request,1,0,null)).status);tenant();request.setAttribute("health.tenant","bad");safe(()->store.requests(request,1,0,null));platform();assertEquals(403,assertThrows(ApiException.class,()->store.list(request,1)).status);verifyNoInteractions(executor);}
 @Test void requiredJoinErrorsAndCommitFailureNeverPartial(){rows(List.of(audit(1)));assertThrows(RuntimeException.class,()->manager.outer(()->{store.list(request,1);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancellation");}));assertEquals("rollback",manager.events.getLast());rows(List.of(audit(1)));manager.failCommit=true;safe(()->store.list(request,1));doThrow(new RuntimeException(new java.sql.SQLException("private",null,51001))).when(executor).execute(any(),any(),any(Object[].class));assertEquals(403,assertThrows(ApiException.class,()->store.list(request,1)).status);}
 @Test void fullList200AndRequestRowsKeepOrderTypesNullsAndOnlyApprovedColumns(){var input=new ArrayList<Map<String,Object>>();for(int i=0;i<200;i++){var row=audit(200-i);row.put("passwordHash","private");input.add(row);}rows(input);var result=store.list(request,999);assertEquals(200,result.size());assertEquals(200L,result.getFirst().get("id"));assertEquals(1L,result.getLast().get("id"));assertEquals(6,result.getFirst().size());assertNull(result.getFirst().get("actorId"));assertEquals("opaque-not-uuid",result.getFirst().get("targetId"));assertThrows(UnsupportedOperationException.class,result::clear);var trace=trace(TENANT);trace.put("cookie","private");rows(List.of(trace));var requests=store.requests(request,1,-1," ");assertEquals(11,requests.getFirst().size());assertEquals(Long.MAX_VALUE,requests.getFirst().get("durationMs"));assertNull(requests.getFirst().get("actorName"));assertEquals(Arrays.asList(1,0,null),args.getLast());}
 @Test void journeyRejectsWrongIdsResultsetsCardinalityAndOverlongSteps(){var wrong=trace(TENANT);wrong.put("id",OTHER);results.add(new SqlServerExecutor.Result(List.of(List.of(wrong),List.of()),List.of()));safe(()->store.journey(request,ID));results.add(new SqlServerExecutor.Result(List.of(List.of(trace(TENANT),trace(TENANT)),List.of()),List.of()));safe(()->store.journey(request,ID));rows(List.of(trace(TENANT)));safe(()->store.journey(request,ID));var many=new ArrayList<Map<String,Object>>();for(int i=0;i<202;i++)many.add(event(i+1,TENANT));results.add(new SqlServerExecutor.Result(List.of(List.of(trace(TENANT)),many),List.of()));safe(()->store.journey(request,ID));}
 @Test void everyApprovedEventColumnIsRequiredAndTyped(){for(String key:event(1,TENANT).keySet()){var row=event(1,TENANT);row.remove(key);rows(List.of(row));safe(()->store.events(request,null,null,null,null,null,null,0,1));assertEquals("rollback",manager.events.getLast());}for(Object scalar:Arrays.asList(null,true,"literal",new BigDecimal("1.25"),List.of("array"))){var row=event(1,TENANT);row.put("metadata",scalar);rows(List.of(row));assertEquals(scalar,((Map<?,?>)((List<?>)store.events(request,null,null,null,null,null,null,0,1).get("items")).getFirst()).get("metadata"));}}

}
